.budget-slider-stage {
  padding: 32px 16px;
  display: flex;
  justify-content: center;
  align-items: center;

  font-family: ui-sans-serif, "Inter", "Helvetica Neue", Arial, sans-serif;
}

.budget-card {
  --safe: #17e88f;
  --warn: #ffb020;
  --danger: #ff3550;
  --ember: #ff8a1e;
  --ink: #0a0a0a;
  --paper: #f7f4ea;
  --paper-2: #ece7d6;
  --steps: 21;
  --percent: 25;
  box-sizing: border-box;
  width: min(320px, 100%);
  background: var(--paper);
  border: 3px solid var(--ink);
  border-radius: 16px;
  padding: 18px 16px 14px;
  position: relative;
  isolation: isolate;
  box-shadow:
    3px 3px 0 0 var(--live-color, var(--safe)),
    7px 7px 0 0 var(--ink);
  transition:
    box-shadow 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.budget-card:hover {
  transform: translate(-1px, -1px);
  box-shadow:
    4px 4px 0 0 var(--live-color, var(--safe)),
    9px 9px 0 0 var(--ink);
}

.budget-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: linear-gradient(
      rgba(10, 10, 10, 0.035) 1px,
      transparent 1px
    ),
    linear-gradient(90deg, rgba(10, 10, 10, 0.035) 1px, transparent 1px);
  background-size: 16px 16px;
  pointer-events: none;
  z-index: 0;
}

.budget-card::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    circle at 50% 15%,
    rgba(255, 53, 80, 0.28),
    transparent 65%
  );
  opacity: 0;
  pointer-events: none;
  z-index: 0;
  transition: opacity 0.3s ease;
}

.budget-card > * {
  position: relative;
  z-index: 1;
}

.budget-card {
  --p1: clamp(0%, calc((var(--percent) * 1% - 0%) / 0.6), 100%);
  --p2: clamp(0%, calc((var(--percent) * 1% - 60%) / 0.4), 100%);
  --stage-color: color-mix(in oklch, var(--safe), var(--warn) var(--p1));
  --live-color: color-mix(
    in oklch,
    var(--stage-color),
    var(--danger) var(--p2)
  );
}

