.status-badge .tier {
  display: none;
  align-items: center;
  gap: 4px;
}
.status-badge .tier[data-tier="safe"] {
  display: inline-flex;
}

.budget-card:has(#s13:checked, #s14:checked, #s15:checked)
  .status-badge
  .tier[data-tier="safe"] {
  display: none;
}
.budget-card:has(#s13:checked, #s14:checked, #s15:checked)
  .status-badge
  .tier[data-tier="caution"] {
  display: inline-flex;
}

.budget-card:has(
    #s16:checked,
    #s17:checked,
    #s18:checked,
    #s19:checked,
    #s20:checked
  )
  .status-badge
  .tier[data-tier="safe"] {
  display: none;
}
.budget-card:has(
    #s16:checked,
    #s17:checked,
    #s18:checked,
    #s19:checked,
    #s20:checked
  )
  .status-badge
  .tier[data-tier="danger"] {
  display: inline-flex;
}

.budget-card:has(
    #s16:checked,
    #s17:checked,
    #s18:checked,
    #s19:checked,
    #s20:checked
  ) {
  animation: budget-panic-shake 0.32s cubic-bezier(0.36, 0.07, 0.19, 0.97)
    infinite;
}

.budget-card:has(
    #s16:checked,
    #s17:checked,
    #s18:checked,
    #s19:checked,
    #s20:checked
  )::after {
  opacity: 1;
  animation: budget-vignette-pulse 0.9s ease-in-out infinite;
}

@keyframes budget-vignette-pulse {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

@keyframes budget-panic-shake {
  0% {
    transform: translate(0, 0) rotate(0deg) scale(1);
  }
  12% {
    transform: translate(-1.6px, 0.9px) rotate(-0.5deg) scale(1.002);
  }
  24% {
    transform: translate(1.4px, -0.7px) rotate(0.5deg) scale(1);
  }
  36% {
    transform: translate(-1.3px, -1px) rotate(-0.35deg) scale(1.002);
  }
  48% {
    transform: translate(1.6px, 0.8px) rotate(0.4deg) scale(1);
  }
  60% {
    transform: translate(-1px, 0.9px) rotate(-0.25deg) scale(1.002);
  }
  72% {
    transform: translate(1.1px, -0.7px) rotate(0.3deg) scale(1);
  }
  84% {
    transform: translate(-0.7px, 0.5px) rotate(-0.15deg) scale(1);
  }
  100% {
    transform: translate(0, 0) rotate(0deg) scale(1);
  }
}

.budget-card:has(
    #s16:checked,
    #s17:checked,
    #s18:checked,
    #s19:checked,
    #s20:checked
  )
  .tick::after {
  animation: budget-thumb-jitter 0.26s ease-in-out infinite;
}

@keyframes budget-thumb-jitter {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(1) rotate(0deg);
  }
  50% {
    transform: translate(-50%, -50%) scale(1.14) rotate(-2deg) translateY(-1px);
  }
}

.budget-card .card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.budget-card .header-text .label {
  display: block;
  font-weight: 800;
  font-size: 12px;
  letter-spacing: -0.01em;
  color: var(--ink);
  margin-bottom: 2px;
}

.budget-card .header-text .sub {
  display: block;
  font-size: 9px;
  color: #767065;
  line-height: 1.3;
  max-width: 20ch;
}

.budget-card .status-badge {
  box-sizing: border-box;
  flex: none;
  display: inline-flex;
  align-items: center;
  padding: 4px 8px 4px 5px;
  border: 2px solid var(--ink);
  border-radius: 999px;
  font-weight: 800;
  font-size: 9px;
  letter-spacing: 0.01em;
  background: var(--live-color);
  color: var(--ink);
  box-shadow: 1px 1px 0 0 var(--ink);
  transition: background 0.15s linear;
}

.budget-card .tier-icon {
  width: 9px;
  height: 9px;
  margin-right: 3px;
  position: relative;
  flex: none;
}

.budget-card .tier[data-tier="safe"] .tier-icon::before {
  content: "";
  position: absolute;
  left: 1px;
  top: 3px;
  width: 3.5px;
  height: 2px;
  border-left: 1.5px solid var(--ink);
  border-bottom: 1.5px solid var(--ink);
  transform: rotate(-45deg);
}

.budget-card .tier[data-tier="caution"] .tier-icon {
  width: 0;
  height: 0;
  margin-right: 5px;
  margin-left: 1px;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-bottom: 6px solid var(--ink);
}

.budget-card .tier[data-tier="danger"] .tier-icon::before {
  content: "";
  position: absolute;
  left: 3.5px;
  top: 0;
  width: 2px;
  height: 4.5px;
  background: var(--ink);
  border-radius: 0.5px;
}

.budget-card .tier[data-tier="danger"] .tier-icon::after {
  content: "";
  position: absolute;
  left: 3.5px;
  top: 6.5px;
  width: 2px;
  height: 2px;
  background: var(--ink);
  border-radius: 50%;
}

.budget-card .value-display {
  display: flex;
  align-items: baseline;
  gap: 3px;
  margin: 10px 0 16px;
}

.budget-card .value-display .currency {
  font-size: 19px;
  font-weight: 800;
  color: var(--live-color);
  transition: color 0.15s linear;
}

.budget-card .live-amount {
  position: relative;
  font-family: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas,
    monospace;
  font-size: 32px;
  font-weight: 700;
  line-height: 1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.015em;
}

.budget-card .live-amount::before {
  content: "2,500";
}

.budget-card .live-amount::after {
  content: attr(data-ghost);
  position: absolute;
  inset: 0;
  z-index: -1;
  color: var(--live-color);
  filter: blur(10px);
  opacity: 0.3;
}

.budget-card .value-display .per-month {
  font-size: 10px;
  font-weight: 700;
  color: #8a8478;
  margin-left: 2px;
  align-self: flex-end;
  margin-bottom: 3px;
}

.budget-card .slider-wrap {
  position: relative;
  height: 58px;
}

.budget-card .live-tooltip {
  box-sizing: border-box;
  position: absolute;
  top: -2px;
  left: 26.19%;
  transform: translate(-50%, -5px) scale(0.85);
  background: var(--ink);
  color: var(--paper);
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-weight: 700;
  font-size: 10px;
  padding: 4px 7px;
  border-radius: 5px;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transition:
    opacity 0.18s cubic-bezier(0.34, 1.56, 0.64, 1),
    transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1),
    left 0.18s ease;
  z-index: 6;
}

.budget-card .live-tooltip::before {
  content: "$2,500";
}

.budget-card .live-tooltip::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 3px solid transparent;
  border-top-color: var(--ink);
}

.budget-card .slider-wrap:hover .live-tooltip,
.budget-card .slider-wrap:focus-within .live-tooltip {
  opacity: 1;
  transform: translate(-50%, 0) scale(1);
}

.budget-card .track-marks {
  position: absolute;
  left: 0;
  right: 0;
  top: 22px;
  height: 14px;
  display: flex;
  justify-content: space-between;
  padding: 0 1px;
  pointer-events: none;
}

.budget-card .track-marks span {
  width: 1.5px;
  height: 4px;
  background: rgba(10, 10, 10, 0.18);
  border-radius: 0.5px;
  align-self: flex-start;
  margin-top: 10px;
}

.budget-card .track-marks span:first-child,
.budget-card .track-marks span:last-child {
  opacity: 0;
}

.budget-card .track-base {
  box-sizing: border-box;
  position: absolute;
  left: 0;
  right: 0;
  top: 29px;
  height: 10px;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--paper-2);
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(10, 10, 10, 0.12);
}

.budget-card .track-fill {
  position: absolute;
  inset: 0;
  width: calc(var(--percent) * 1%);
  background: var(--live-color);
  box-shadow: 0 0 14px 1px var(--live-color);
  transition: box-shadow 0.15s linear;
}

.budget-card .track-fill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.28) 0 5px,
    transparent 5px 10px
  );
  opacity: 0.5;
}

.budget-card .track-fill::before {
  content: "";
  position: absolute;
  right: -1px;
  top: 0;
  bottom: 0;
  width: 12px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.5));
  opacity: 0.6;
}

.budget-card .steps-row {
  position: absolute;
  left: 0;
  right: 0;
  top: 18px;
  height: 26px;
  display: flex;
  flex-direction: row-reverse;
  z-index: 3;
}

.budget-card .step {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.budget-card .tick {
  position: relative;
  flex: 1 0 calc(100% / var(--steps));
  height: 26px;
  cursor: pointer;
}

.budget-card .tick::before {
  content: "";
  position: absolute;
  top: 50%;
  left: -1px;
  right: -1px;
  height: 10px;
  transform: translateY(-50%);
  background: transparent;
  transition: background 0.1s linear;
}

.budget-card .step:checked ~ .tick::before {
  background: var(--live-color);
}

.budget-card .tick::after {
  box-sizing: border-box;
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #ffffff, var(--paper) 62%);
  border: 3px solid var(--ink);
  transform: translate(-50%, -50%) scale(0);
  transition:
    transform 0.32s cubic-bezier(0.34, 1.56, 0.64, 1),
    border-color 0.15s linear,
    box-shadow 0.15s linear;
  z-index: 4;
}

.budget-card .step:checked + .tick::after {
  transform: translate(-50%, -50%) scale(1);
  border-color: var(--live-color);
  box-shadow:
    0 0 0 3px var(--ink),
    0 0 0 5px rgba(247, 244, 234, 0.9),
    0 0 16px 2px var(--live-color),
    inset 0 -2px 3px rgba(10, 10, 10, 0.18);
}

.budget-card .step:focus-visible + .tick::after {
  box-shadow:
    0 0 0 3px var(--ink),
    0 0 0 6px var(--paper),
    0 0 0 9px var(--live-color);
}

.budget-card .tick:hover::after {
  transform: translate(-50%, -50%) scale(0.55);
  background: var(--paper-2);
  border-color: rgba(10, 10, 10, 0.3);
}

.budget-card .step:checked + .tick:hover::after {
  transform: translate(-50%, -50%) scale(1.08) translateY(-0.5px);
}

.budget-card .tick:active::after {
  transform: translate(-50%, -50%) scale(0.82);
  transition-duration: 0.06s;
}

.budget-card .step:checked + .tick:active::after {
  transform: translate(-50%, -50%) scale(0.88);
}

.budget-card .fx-anchor {
  position: absolute;
  left: 26.19%;
  top: 18px;
  width: 26px;
  height: 26px;
  pointer-events: none;
  z-index: 5;
}

.budget-card .shock-ring {
  box-sizing: border-box;
  position: absolute;
  top: 50%;
  left: 50%;
  width: 18px;
  height: 18px;
  margin: -9px 0 0 -9px;
  border: 1.5px solid var(--danger);
  border-radius: 50%;
  opacity: 0;
}

.budget-card:has(
    #s16:checked,
    #s17:checked,
    #s18:checked,
    #s19:checked,
    #s20:checked
  )
  .shock-ring {
  animation: budget-shock-expand 1.1s ease-out infinite;
}

.budget-card .shock-ring:nth-child(2) {
  animation-delay: 0.4s !important;
}

@keyframes budget-shock-expand {
  0% {
    opacity: 0.65;
    transform: scale(0.6);
  }
  100% {
    opacity: 0;
    transform: scale(2.4);
  }
}

.budget-card .spark {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 3.5px;
  height: 3.5px;
  margin: -1.75px 0 0 -1.75px;
  border-radius: 50%;
  background: var(--danger);
  box-shadow: 0 0 4px 0.5px var(--danger);
  opacity: 0;
}

.budget-card:has(
    #s16:checked,
    #s17:checked,
    #s18:checked,
    #s19:checked,
    #s20:checked
  )
  .spark {
  animation: budget-spark-scatter 1s ease-out infinite;
}

.budget-card .spark:nth-child(3) {
  animation-delay: 0s;
  --dx: -20px;
  --dy: -15px;
  --sz: 3.5px;
  background: var(--ember);
  box-shadow: 0 0 4px 0.5px var(--ember);
}
.budget-card .spark:nth-child(4) {
  animation-delay: 0.09s;
  --dx: 18px;
  --dy: -18px;
  --sz: 2.5px;
}
.budget-card .spark:nth-child(5) {
  animation-delay: 0.18s;
  --dx: -14px;
  --dy: 14px;
  --sz: 3.5px;
}
.budget-card .spark:nth-child(6) {
  animation-delay: 0.27s;
  --dx: 15px;
  --dy: 16px;
  --sz: 2.5px;
  background: var(--ember);
  box-shadow: 0 0 4px 0.5px var(--ember);
}
.budget-card .spark:nth-child(7) {
  animation-delay: 0.36s;
  --dx: 0px;
  --dy: -23px;
  --sz: 3.5px;
}
.budget-card .spark:nth-child(8) {
  animation-delay: 0.45s;
  --dx: -24px;
  --dy: 1px;
  --sz: 2.5px;
}
.budget-card .spark:nth-child(9) {
  animation-delay: 0.54s;
  --dx: 23px;
  --dy: 3px;
  --sz: 3.5px;
  background: var(--ember);
  box-shadow: 0 0 4px 0.5px var(--ember);
}
.budget-card .spark:nth-child(10) {
  animation-delay: 0.63s;
  --dx: 3px;
  --dy: 19px;
  --sz: 2.5px;
}
.budget-card .spark:nth-child(11) {
  animation-delay: 0.72s;
  --dx: -7px;
  --dy: -25px;
  --sz: 2px;
}
.budget-card .spark:nth-child(12) {
  animation-delay: 0.81s;
  --dx: 9px;
  --dy: 24px;
  --sz: 2px;
}

.budget-card .spark {
  width: var(--sz, 3.5px);
  height: var(--sz, 3.5px);
  margin-top: calc(var(--sz, 3.5px) / -2);
  margin-left: calc(var(--sz, 3.5px) / -2);
}

@keyframes budget-spark-scatter {
  0% {
    opacity: 0;
    transform: translate(0, 0) scale(0.3) rotate(0deg);
  }
  18% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translate(var(--dx), var(--dy)) scale(1) rotate(80deg);
  }
}

.budget-card .scale {
  display: flex;
  justify-content: space-between;
  margin-top: 3px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: #8a8478;
  font-family: "JetBrains Mono", ui-monospace, monospace;
}

.budget-card .card-footnote {
  box-sizing: border-box;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1.5px dashed rgba(10, 10, 10, 0.14);
  font-size: 9px;
  color: #8a8478;
  line-height: 1.4;
}

.budget-card .card-footnote strong {
  color: var(--ink);
}

@media (prefers-reduced-motion: reduce) {
  .budget-card,
  .budget-card::after,
  .budget-card .tick::after,
  .budget-card .spark,
  .budget-card .shock-ring {
    animation: none !important;
  }
}

@media (max-width: 420px) {
  .budget-card .live-amount {
    font-size: 28px;
  }
  .budget-card {
    padding: 15px 13px 11px;
    box-shadow:
      2px 2px 0 0 var(--live-color, var(--safe)),
      5px 5px 0 0 var(--ink);
  }
  .budget-card .header-text .sub {
    max-width: 16ch;
  }
}
